import { revalidatePath } from 'next/cache'

// Simple in-memory storage for demo purposes
// In a real app, this would be a database
let userPreferences = {
  notificationsEnabled: false
}

export async function toggleNotificationPreference() {
  // Toggle the preference
  userPreferences.notificationsEnabled = !userPreferences.notificationsEnabled

  // Revalidate the current page to show updated preference
  revalidatePath('/')

  return {
    success: true,
    notificationsEnabled: userPreferences.notificationsEnabled
  }
}

export async function getNotificationPreference() {
  return {
    notificationsEnabled: userPreferences.notificationsEnabled
  }
}

