'use client'

import { useState, useEffect } from 'react'
import { toggleNotificationPreference, getNotificationPreference } from './actions'

export default function Home() {
  const [notificationsEnabled, setNotificationsEnabled] = useState<boolean | null>(null)

  useEffect(() => {
    // Fetch initial preference
    async function fetchPreference() {
      try {
        const result = await getNotificationPreference()
        setNotificationsEnabled(result.notificationsEnabled)
      } catch (error) {
        console.error('Failed to fetch notification preference:', error)
      }
    }
    fetchPreference()
  }, [])

  const handleToggle = async () => {
    if (notificationsEnabled === null) return

    try {
      // Optimistic update
      setNotificationsEnabled(!notificationsEnabled)

      // Call server action
      await toggleNotificationPreference()

      // Note: revalidatePath in the server action will refresh the page
      // This is handled server-side, so we don't need additional client-side refresh logic here
    } catch (error) {
      console.error('Failed to toggle notification preference:', error)
      // Revert optimistic update on error
      setNotificationsEnabled(notificationsEnabled)
    }
  }

  if (notificationsEnabled === null) {
    return (
      <main className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <h1 className="text-2xl font-bold mb-4">Settings</h1>
          <p className="text-gray-600">Loading notification preferences...</p>
        </div>
      </main>
    )
  }

  return (
    <main className="min-h-screen flex items-center justify-center bg-gray-50">
      <div className="bg-white p-8 rounded-lg shadow-md w-full max-w-md">
        <h1 className="text-2xl font-bold mb-6 text-center">Settings</h1>

        <div className="space-y-4">
          <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg">
            <div>
              <h3 className="font-medium text-gray-900">Notifications</h3>
              <p className="text-sm text-gray-600">
                {notificationsEnabled 
                  ? 'Currently enabled' 
                  : 'Currently disabled'
                }
              </p>
            </div>

            <form action={toggleNotificationPreference}>
              <button
                type="submit"
                className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                  notificationsEnabled ? 'bg-blue-600' : 'bg-gray-200'
                }`}
              >
                <span
                  className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                    notificationsEnabled ? 'translate-x-3' : 'translate-x-1'
                  }`}
                />
              </button>
            </form>
          </div>

          <div className="mt-6 p-4 bg-blue-50 rounded-lg">
            <p className="text-sm text-blue-800">
              <strong>How this works:</strong> The toggle button calls a Server Action that:
            </p>
            <ul className="mt-2 text-sm text-blue-700 list-disc list-inside">
              <li>Toggles the notification preference</li>
              <li>Uses <code className="bg-blue-100 px-1 rounded">revalidatePath('/')</code> to refresh the page</li>
              <li>Shows the updated preference without redirecting</li>
            </ul>
          </div>
        </div>
      </div>
    </main>
  )
}

